/**
 * Wire types — the single place the SSE client indexes into the generated
 * OpenAPI types (src/generated/api-types.d.ts, ADR-0012). Components and the
 * api/sse modules import from here, never from the generated file directly, so
 * the `components["schemas"][…]` indexing lives in exactly one spot.
 *
 * The generated file is a build product (READ-ONLY here — regenerated by
 * `npm run api:dump && npm run api:types`). This module only re-aliases it.
 */
import type { components } from '../generated/api-types'

type Schemas = components['schemas']

// Request bodies (POST event-stream routes).
export type AppealRequest = Schemas['AppealRequest']
export type ResumeAppealRequest = Schemas['ResumeAppealRequest']
export type InitialPaRequest = Schemas['InitialPaRequest']

// Auth (session-cookie BFF, ADR-0013).
export type LoginRequest = Schemas['LoginRequest']
export type LoginResponse = Schemas['LoginResponse']
export type MeResponse = Schemas['MeResponse']

// Review-queue item (metadata only — never letter text).
export type PendingReviewItem = Schemas['PendingReviewItem']

// SSE event shapes (registered from Pydantic via backend/openapi_ext.py).
export type StepEvent = Schemas['StepEvent']
export type ChunkEvent = Schemas['ChunkEvent']
export type DoneEvent = Schemas['DoneEvent']
export type StreamErrorEvent = Schemas['ErrorEvent']
export type InitialPaDoneEvent = Schemas['InitialPaDoneEvent']

// GET introspection responses.
export type AuditRecordsResponse = Schemas['AuditRecordsResponse']
export type PendingReviewsResponse = Schemas['PendingReviewsResponse']

/**
 * Per-route discriminated event unions. Every member carries an `event` field
 * (Pydantic const default), so callers narrow on `event`. Each stream ends
 * after exactly one terminal (`done`/`error`) event (06-api-contract.md).
 *
 * `DoneEvent` and `InitialPaDoneEvent` both discriminate as `event: "done"`,
 * so they never share a union — the appeal/resume streams carry the former,
 * the initial-PA stream the latter.
 */
export type AppealEvent = StepEvent | ChunkEvent | DoneEvent | StreamErrorEvent
export type ResumeEvent = StepEvent | DoneEvent | StreamErrorEvent
export type PaSubmitEvent = StepEvent | InitialPaDoneEvent | StreamErrorEvent
